private theorem exists_map_eq_of_nodup (xs ys : List I)
    (hxs : xs.Nodup) (hys : ys.Nodup) (hlength : xs.length = ys.length) :
    ∃ σ : Equiv.Perm I, xs.map σ = ys

private theorem count_event_invariant (n : ℕ) :
    ∀ (σ : Equiv.Perm (Fin 3)), (∀ a, σ a ∈ selected ↔ a ∈ selected) →
      ∀ π, (π * σ.symm ∈ countEvent n ↔ π ∈ countEvent n)

private theorem count_order_slice (n : ℕ) (xs : List (Fin 3)) :
    law3 (countEvent n ∩ orderEvent xs) =
      if xs ∈ orders positions selected then law3 (countEvent n) / 2 else 0

private theorem independent_cell (n : ℕ) (xs : List (Fin 3)) :
    law3 (countEvent n ∩ orderEvent xs) =
      law3 (countEvent n) * law3 (orderEvent xs)
